* { box-sizing: border-box; }
body { margin: 0; background: #000; color: var(--ink); font: 14px/1.55 var(--body); }
button, input, select { font: inherit; color: inherit; }
button, a, input, select, summary { touch-action: manipulation; }
button, select, summary { cursor: pointer; }
button:disabled { opacity: .58; cursor: default; }
[hidden] { display: none !important; }
a { color: inherit; }
:focus-visible { outline: 2px solid var(--focus); outline-offset: 4px; }
h1, h2, h3, h4 { font-family: var(--display); font-weight: 400; }
h1 { margin: 0 0 24px; font-size: clamp(36px, 5vw, 66px); line-height: 1.05; letter-spacing: -.045em; }
