h1 { margin: 0 0 24px; font-size: clamp(36px, 5vw, 66px); line-height: 1.05; letter-spacing: -.045em; }
h1:focus { outline: none; }
h2 { font-size: 19px; margin: 0; }

.workspace {
  display: grid;
  grid-template-columns: minmax(250px, .24fr) minmax(0, 1.4fr) minmax(230px, .28fr);
  align-items: stretch;
  gap: 12px 0;
  transition: grid-template-columns .8s var(--ease-out);
}
.workspace[data-stage="setup"] { grid-template-columns: minmax(0, 1fr) minmax(0, 0fr) minmax(0, 0fr); }
.workspace:is([data-stage="running"], [data-stage="interrupted"]) { grid-template-columns: minmax(0, 1fr) minmax(0, 1fr) minmax(0, 0fr); }
@media (min-width: 961px) {
  .workspace[data-stage="complete"] { align-items: start; }
  #workspace[data-stage="complete"] #plot { max-height: max(380px, calc(100svh - 170px)); }
}
.workspace[data-stage="running"] .setup { display: flex; flex-direction: column; }
.workspace[data-stage="running"] .setup form { max-width: 500px; width: 100%; margin-inline: auto; }
.workspace[data-stage="running"] .setup #status { margin-top: auto; padding-top: 20px; }
.workspace .diagram-panel, .workspace .inspector { margin-left: 12px; }
.workspace .diagram-panel:not([hidden]), .workspace .inspector:not([hidden]) { animation: panel-unfold .8s var(--ease-out) both; transform-origin: top left; }
@keyframes panel-unfold {
  from { opacity: 0; clip-path: polygon(0 0, 0 0, 0 0); transform: scale(.96); }
  to { opacity: 1; clip-path: polygon(0 0, 200% 0, 0 200%); transform: scale(1); }
}
.panel {
  min-width: 0;
  border: 1px solid var(--line);
  border-radius: 22px;
  background: linear-gradient(150deg, #272a31de, #14171cde 55%, #101216e8);
  box-shadow: inset 0 1px #ffffff20, 0 16px 48px #0007;
  backdrop-filter: blur(16px) saturate(.8);
}
.setup, .inspector, .diagram-panel { padding: 22px 18px; }
.section-heading { margin-bottom: 16px; }
label { display: block; font-size: 13px; margin: 15px 0 6px; }
.two-col { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); gap: 10px; }
.two-col label { margin-top: 0; }
.elements { margin-top: 15px; }
input:not([type="radio"], [type="checkbox"]), select {
  width: 100%;
  min-height: 42px;
  border: 1px solid var(--line);
  border-radius: 9px;
  padding: 8px 10px;
  background: #080b11b0;
  font-size: 13px;
}
select { padding-right: 20px; text-overflow: ellipsis; }
input[type="file"] { text-overflow: ellipsis; }
input::file-selector-button {
  border: 1px solid #ffffff30;
  border-radius: 6px;
  background: linear-gradient(#414752, #242934);
  color: var(--ink);
  font: inherit;
